  // Whole seconds since epoch (floor so pre-epoch instants round toward the past)
  const secs = Math.floor(epochMs / 1000);

  // Split into days and seconds-of-day (floor division for negatives)
  const days = Math.floor(secs / 86400);
  const sod = secs - days * 86400;

  const hh = Math.floor(sod / 3600);
  const mm = Math.floor((sod % 3600) / 60);
  const ss = sod % 60;

  // Civil date from day count (days since 1970-01-01), proleptic Gregorian
  const z = days + 719468;
