  // Luhn algorithm: from the rightmost digit, double every second digit.
  let sum = 0;
  let double = false;
  for (let i = expanded.length - 1; i >= 0; i--) {
    let d = expanded.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }

