  for (let i = 0; i < 7; i++) {
    sum += (8 - i) * (digits.charCodeAt(i) - 48);
  }

  const last = digits[7];
  const check = last === "X" || last === "x" ? 10 : last.charCodeAt(0) - 48;
  sum += check;

  return sum % 11 === 0;
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  if (!/^[0-9]+$/.test(code)) return false;

  const n = code.length;
  if (n !== 8 && n !== 13 && n !== 14) return false;

  // Weights alternate 3, 1, 3, ... starting from the digit just left of the check digit.
  let sum = 0;
  for (let i = 0; i < n - 1; i++) {
    const digit = code.charCodeAt(i) - 48;
    const fromRight = n - 2 - i; // 0 for the digit adjacent to the check digit
    sum += digit * (fromRight % 2 === 0 ? 3 : 1);
  }

  const check = (10 - (sum % 10)) % 10;
  return check === code.charCodeAt(n - 1) - 48;
}

